<?php namespace App\Http\Controllers\Author; use App\Http\Controllers\Controller; use App\Models\Product; use App\Models\ProductVersion; use App\Models\User; use App\Notifications\MarketplaceNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class ProductUpdateController extends Controller { public function store(Request $r,Product $product){abort_unless($product->author_id===Auth::id(),403);abort_unless($product->status==="published",422,"Only published products can receive an update.");$v=$r->validate(["change_summary"=>["required","string","max:5000"],"snapshot"=>["required","array"],"snapshot.file"=>["required","string","max:1000"],"snapshot.version"=>["required","string","max:50"],"submit"=>["nullable","boolean"]]);$existing=$product->versions()->whereIn("status",["draft","pending","changes_requested"])->latest()->first();if($existing&&$existing->status==="pending")abort(422,"An update is already awaiting review.");$payload=["snapshot"=>$v["snapshot"],"change_summary"=>$v["change_summary"],"status"=>($v["submit"]??false)?"pending":"draft","submitted_by"=>Auth::id(),"submitted_at"=>($v["submit"]??false)?now():null];if($existing){$existing->update($payload);$version=$existing;}else{$version=ProductVersion::create($payload+["product_id"=>$product->id,"version_number"=>max((int)$product->versions()->max("version_number"),(int)preg_replace("/\\D.*/","",$product->version))+1]);}if($version->status==="pending")User::whereIn("role",["superadmin","admin"])->get()->each(fn($staff)=>$staff->notify(new MarketplaceNotification(["title"=>"Product update submitted","body"=>$product->name." has a new file awaiting review.","url"=>"/admin/products","kind"=>"review"])));return response()->json(["message"=>$version->status==="pending"?"Update submitted. The live file remains available until approval.":"Update draft saved.","version"=>$version]);} }